import {buildPublicView,addressMatches} from './public-radar.mjs';
import {read,toggleSaved,isSaved,esc,ago,safeURL} from './research-store.mjs';
const $=id=>document.getElementById(id),id=new URLSearchParams(location.search).get('id');
const articles=read('meme-fast-public-articles-v1',[]),coins=read('meme-fast-public-coins-v1',[]);
const narrative=buildPublicView({articles,coins},{hours:72},Date.now()).all.find(item=>item.id===id);
function draw(){
 if(!narrative){$('title').textContent='Narrative unavailable';$('summary').textContent='This narrative is not in this browser’s recent observation history.';$('content').innerHTML='<div class="empty-workspace"><strong>Return to Tweet to collect current signals.</strong>Narrative IDs are derived from observed articles. A future backend will make these pages durable and shareable.<br><br><a class="primary" href="./narratives.html">Open Tweet</a></div>';return}
 const sources=new Set(narrative.posts.map(p=>p.publisher)),matches=addressMatches(narrative,coins);document.title=narrative.title+' · Meme Fast';$('title').textContent=narrative.title;$('summary').textContent=narrative.summary;$('save').hidden=false;$('save').textContent=isSaved('narrative',narrative.id)?'Saved ✓':'Save narrative';
 $('content').innerHTML=`<div class="research-main"><section class="research-card"><span class="kicker">CURRENT READ</span><div class="status-row"><span class="status-pill accent">${sources.size>=2?'LC1 candidate':'LC0 signal'}</span><span class="status-pill">${esc(narrative.group)}</span><span class="status-pill">72H evidence window</span></div><p>${esc(narrative.summary)}</p></section><section class="research-card"><h2>Evidence trail</h2><div class="evidence-list">${narrative.posts.map(p=>`<a class="evidence-item" href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer"><div><span>${esc(p.publisher)}</span><time>${esc(ago(p.time))}</time></div><strong>${esc(p.title)} ↗</strong></a>`).join('')}</div></section><section class="research-card"><h2>Associated tokens</h2>${matches.length?`<div class="item-list">${matches.map(c=>`<article class="saved-item"><div><h3>$${esc(c.symbol)} · ${esc(c.name)}</h3><p>${esc(c.chain)} · exact contract address appears in evidence</p></div><a href="./?query=${encodeURIComponent(c.contract_address)}">Research flow ↗</a></article>`).join('')}</div>`:'<p>No exact contract-address association was found in the current evidence. Ticker or theme similarity is intentionally not treated as proof.</p>'}</section></div><aside class="research-side"><section class="research-card"><h2>Observed facts</h2><div class="fact-grid"><div class="fact"><span>Publishers</span><strong>${sources.size}</strong></div><div class="fact"><span>Articles</span><strong>${narrative.posts.length}</strong></div><div class="fact"><span>Tokens</span><strong>${matches.length}</strong></div></div></section><section class="research-card"><h2>Lifecycle</h2><div class="roadmap"><div><strong>${sources.size>=2?'Cross-publisher candidate':'Raw news signal'}</strong><span>Current evidence-supported state</span></div><div><strong>Meme formation</strong><span>Needs independent social collection</span></div><div><strong>Market conversion</strong><span>Needs historical token association</span></div></div></section><section class="research-card"><h2>Coverage</h2><p>This view uses public-news observations saved in this browser. Continuous collection, semantic clustering, and verified lifecycle transitions belong to the backend phase.</p></section></aside>`;
}
$('save').onclick=()=>{toggleSaved({type:'narrative',id:narrative.id,title:narrative.title,subtitle:`${sourcesLabel()} · ${narrative.posts.length} articles`,href:`./narrative.html?id=${encodeURIComponent(narrative.id)}`});draw()};
function sourcesLabel(){return `${new Set(narrative.posts.map(p=>p.publisher)).size} publishers`}
draw();
